Client-Server Architecture:
class GameServer {
    constructor() {
        this.clients = new Map();
        this.worldState = {};
        this.tickRate = 20;
    }
    start() {
        setInterval(() => {
            this.processInputs();
            this.updateWorld();
            this.broadcastState();
        }, 1000 / this.tickRate);
    }
    processInputs() {
        for (const [id, client] of this.clients) {
            for (const input of client.inputQueue) {
                this.applyInput(id, input);
            }
            client.inputQueue = [];
        }
    }
    broadcastState() {
        for (const [id, client] of this.clients) {
            const snapshot = this.createSnapshot(id);
            client.send(snapshot);
        }
    }
}

