Scene Management & Multi-Scene:
using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections;

public class SceneLoader : MonoBehaviour {
    public string persistentScene = "UIRoot";

    IEnumerator Start() {
        // Load persistent UI first
        if (!SceneManager.GetSceneByName(persistentScene).isLoaded) {
            yield return SceneManager.LoadSceneAsync(persistentScene, LoadSceneMode.Additive);
        }
    }

    public void LoadLevel(string levelName) {
        // Unload current gameplay scene
        StartCoroutine(SwitchLevel(levelName));
    }

    IEnumerator SwitchLevel(string newLevel) {
        // Find current gameplay scene (not persistent)
        Scene currentGameplay = SceneManager.GetActiveScene();

        // Load new level additively
        yield return SceneManager.LoadSceneAsync(newLevel, LoadSceneMode.Additive);
        SceneManager.SetActiveScene(SceneManager.GetSceneByName(newLevel));

        // Unload old gameplay scene
        if (currentGameplay.name != persistentScene && currentGameplay.isLoaded) {
            yield return SceneManager.UnloadSceneAsync(currentGameplay);
        }
    }

    void OnEnable() => SceneManager.sceneLoaded += OnSceneLoaded;
    void OnDisable() => SceneManager.sceneLoaded -= OnSceneLoaded;

    void OnSceneLoaded(Scene scene, LoadSceneMode mode) {
        Debug.Log($"Loaded {scene.name} ({mode})");
    }
}

