// Emitter Update script
void UpdateParticles()
{
    // Age particles
    float Age = GetParticleAttribute(Particles.Age);
    Age += DeltaTime;
    SetParticleAttribute(Particles.Age, Age);

    // Apply wind force
    float3 Wind = GetDataInstance(FSimpleVelocity.WindForce);
    float3 Velocity = GetParticleAttribute(Particles.Velocity);
    Velocity += Wind * DeltaTime;
    SetParticleAttribute(Particles.Velocity, Velocity);

    // Kill old particles
    float Lifetime = GetParticleAttribute(Particles.Lifetime);
    if (Age >= Lifetime)
        KillParticle();
}

