Control Rig & IK:
// Control Rig C++ (UControlRig)
// Typically done in graph, exposed here for reference
FRigUnit_FABRIK_ItemArray::Execute()
{
    // Forward reach: from root to tip
    for (int32 i = 0; i < Chain.Num(); i++) {
        FTransform& Transform = Transforms[i];
        FVector ToTarget = (Target - Transform.GetLocation()).GetSafeNormal();
        Transform.SetLocation(Transform.GetLocation() + ToTarget * Chain[i].BoneLength);
    }
    // Backward reach: from tip to root maintaining bone lengths
    for (int32 i = Chain.Num() - 2; i >= 0; i--) {
        FVector Direction = (Transforms[i+1].GetLocation() - Transforms[i].GetLocation()).GetSafeNormal();
        Transforms[i + 1].SetLocation(Transforms[i].GetLocation() + Direction * Chain[i].BoneLength);
    }
}

