Physics Integration (Euler, Verlet, RK4):
function euler(pos, vel, accel, dt) {
    pos += vel * dt;
    vel += accel * dt;
}
function verlet(pos, prevPos, accel, dt) {
    const temp = pos;
    pos = 2 * pos - prevPos + accel * dt * dt;
    prevPos = temp;
}
function rk4(state, derivFn, dt) {
    const k1 = derivFn(state);
    const k2 = derivFn(state + k1 * dt * 0.5);
    const k3 = derivFn(state + k2 * dt * 0.5);
    const k4 = derivFn(state + k3 * dt);
    return state + (k1 + 2 * k2 + 2 * k3 + k4) * dt / 6;
}

Friction & Restitution:
function resolveCollision(a, b, normal) {
    const relVel = { x: a.vx - b.vx, y: a.vy - b.vy };
    const velAlongNormal = relVel.x * normal.x + relVel.y * normal.y;
    if (velAlongNormal > 0) return;
    const e = Math.min(a.restitution, b.restitution);
    const j = -(1 + e) * velAlongNormal / (1 / a.mass + 1 / b.mass);
    a.vx += j * normal.x / a.mass;
    a.vy += j * normal.y / a.mass;
    b.vx -= j * normal.x / b.mass;
    b.vy -= j * normal.y / b.mass;
}

Joints & Constraints:
class DistanceJoint {
    constructor(a, b, length) {
        this.a = a; this.b = b; this.length = length;
    }
    solve() {
        const dx = this.b.x - this.a.x;
        const dy = this.b.y - this.a.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const correction = (dist - this.length) / dist * 0.5;
        this.a.x += dx * correction;
        this.a.y += dy * correction;
        this.b.x -= dx * correction;
        this.b.y -= dy * correction;
    }
}

Raycasting:
function rayAABB(rayOrigin, rayDir, aabb) {
    const t1 = (aabb.min.x - rayOrigin.x) / rayDir.x;
    const t2 = (aabb.max.x - rayOrigin.x) / rayDir.x;
    const t3 = (aabb.min.y - rayOrigin.y) / rayDir.y;
    const t4 = (aabb.max.y - rayOrigin.y) / rayDir.y;
    const tmin = Math.max(Math.min(t1, t2), Math.min(t3, t4));
    const tmax = Math.min(Math.max(t1, t2), Math.max(t3, t4));
    return tmax >= Math.max(0, tmin);
}

Spatial Partitioning:
class Quadtree {
    constructor(bounds, capacity = 4) {
        this.bounds = bounds;
        this.capacity = capacity;
        this.objects = [];
        this.divided = false;
    }
    insert(obj) {
        if (!contains(this.bounds, obj)) return false;
        if (this.objects.length < this.capacity) {
            this.objects.push(obj); return true;
        }
        if (!this.divided) this.subdivide();
        return this.nw.insert(obj) || this.ne.insert(obj) ||
               this.sw.insert(obj) || this.se.insert(obj);
    }
    query(range, result = []) {
        if (!intersects(this.bounds, range)) return result;
        for (const obj of this.objects) if (contains(range, obj)) result.push(obj);
        if (this.divided) {
            this.nw.query(range, result);
            this.ne.query(range, result);
            this.sw.query(range, result);
            this.se.query(range, result);
        }
        return result;
    }
}

