function physicsStep(dt) {
    const pairs = broadphase(bodies);
    const contacts = [];
    for (const [a, b] of pairs) {
        const contact = narrowphase(a, b);
        if (contact) contacts.push(contact);
    }
    solveConstraints(contacts);
    for (const body of bodies) {
        body.integrate(dt);
    }
}

