    static rotateX(angle) {
        const c = Math.cos(angle), s = Math.sin(angle);
        return new Mat4([1,0,0,0, 0,c,s,0, 0,-s,c,0, 0,0,0,1]);
    }
    mul(other) {
        const a = this.m, b = other.m, r = [];
        for (let i = 0; i < 4; i++)
            for (let j = 0; j < 4; j++)
                r[i*4+j] = a[i*4+0]*b[0+j] + a[i*4+1]*b[4+j] +
                           a[i*4+2]*b[8+j] + a[i*4+3]*b[12+j];
