Cellular Automata:
function cellularAutomata(grid, rules = 'cave') {
    const h = grid.length, w = grid[0].length;
    const next = Array.from({length: h}, () => new Array(w).fill(0));
    for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
            const neighbors = countNeighbors(grid, x, y);
            if (rules === 'cave') {
                // Cave: fill if >= 5 walls nearby
                next[y][x] = (grid[y][x] === 1 && neighbors >= 4) ||
                             (grid[y][x] === 0 && neighbors >= 5) ? 1 : 0;
            } else {
                // Game of Life
                if (grid[y][x]) next[y][x] = (neighbors === 2 || neighbors === 3) ? 1 : 0;
                else next[y][x] = (neighbors === 3) ? 1 : 0;
            }
        }
    }
    return next;
}

Wave Function Collapse:
function wfc(grid, patterns) {
    // patterns: adjacency rules from example
    // entropy = number of remaining tile options
    while (true) {
        const cell = findLowestEntropy(grid);
        if (!cell) break; // all collapsed
        collapse(cell, patterns);  // choose tile by weight
        propagate(grid, cell, patterns);  // enforce constraints
    }
    return grid;
}

function propagate(grid, cell, patterns) {
    const stack = [cell];
    while (stack.length > 0) {
        const current = stack.pop();
        for (const neighbor of current.neighbors) {
            const valid = getValidNeighborTiles(current, neighbor, patterns);
            if (intersect(neighbor.options, valid).length < neighbor.options.length) {
                neighbor.options = intersect(neighbor.options, valid);
                if (neighbor.options.length === 0) return; // contradiction
                stack.push(neighbor);
            }
        }
    }
}

