function bspDungeon(width, height, minRoomSize) {
    function split(rect, depth) {
        if (rect.w < minRoomSize * 2 || rect.h < minRoomSize * 2 || depth > 4) {
            return [rect]; // leaf: create room
        }
        const horizontal = Math.random() > 0.5;
        if (horizontal && rect.h >= minRoomSize * 2) {
            const split = minRoomSize + Math.random() * (rect.h - minRoomSize * 2);
            return [...split({...rect, h: split}, depth+1),
                    ...split({...rect, y: rect.y+split, h: rect.h-split}, depth+1)];
        }
        // vertical split
    }
    const rooms = split({x:0, y:0, w:width, h:height}, 0);
    return connectRooms(rooms);
}

