Threading & Job Systems:
class JobSystem {
    constructor(threadCount = navigator.hardwareConcurrency - 1) {
        this.queue = [];
        this.workers = [];
        for (let i = 0; i < threadCount; i++) {
            const worker = new Worker('job-worker.js');
            worker.onmessage = e => this.onComplete(e.data);
            this.workers.push(worker);
        }
    }
    schedule(job) {
        this.queue.push(job);
        this.dispatch();
    }
    dispatch() {
        for (const worker of this.workers) {
            if (worker.busy || this.queue.length === 0) continue;
            worker.busy = true;
            worker.postMessage(this.queue.shift());
        }
    }
    onComplete(result) {
        result.worker.busy = false;
        this.dispatch();
        // Main thread: use result
    }
}

