class LODSystem {
    constructor(camera) {
        this.camera = camera;
        this.groups = [];
    }
    register(mesh, lods) {
        // lods = [{ mesh, materials, maxDistance }, ...]
        this.groups.push({ mesh, lods, currentLod: -1 });
    }
    update() {
        for (const group of this.groups) {
            const dist = distance(this.camera.position, group.mesh.position);
            let lod = 0;
            while (lod < group.lods.length - 1 && dist > group.lods[lod].maxDistance) lod++;
            if (lod !== group.currentLod) {
                group.mesh.switchTo(group.lods[lod]);
                group.currentLod = lod;
            }
        }
    }
}

