class SaveManager {
    constructor() {
        this.SAVE_VERSION = 3;
    }
    async save(slot, data) {
        const package = {
            version: this.SAVE_VERSION,
            timestamp: Date.now(),
            playerName: data.playerName,
            data: this.compress(JSON.stringify(data)),
            checksum: ''
        };
        package.checksum = this.crc32(JSON.stringify(package));
        // Atomic write: write to temp, then rename
        const tmpPath = `save_${slot}.tmp`;
        await writeFile(tmpPath, JSON.stringify(package));
        await rename(tmpPath, `save_${slot}.json`);
    }
    async load(slot) {
        const raw = await readFile(`save_${slot}.json`);
        const package = JSON.parse(raw);
        const checksum = this.crc32(JSON.stringify({ ...package, checksum: '' }));
        if (checksum !== package.checksum) throw new Error('Save corrupted');
        return JSON.parse(this.decompress(package.data));
    }
}

Cloud Saves & Sync:
class CloudSaveService {
    async sync(saves) {
        const remote = await this.fetchRemoteSaves();
        for (const [slot, local] of Object.entries(saves)) {
            const remoteSlot = remote[slot];
            if (!remoteSlot || local.timestamp > remoteSlot.timestamp) {
                await this.upload(slot, local);
            } else if (local.timestamp < remoteSlot.timestamp) {
                saves[slot] = remoteSlot; // download newer
            }
            // Conflict: merge if both changed
            if (remoteSlot && Math.abs(local.timestamp - remoteSlot.timestamp) < 5000) {
                saves[slot] = this.merge(local, remoteSlot);
            }
        }
        return saves;
    }
    merge(a, b) {
        return { ...a, ...b, inventory: [...new Set([...a.inventory, ...b.inventory])] };
    }
}

