    async cook(inputPath, outputPath) {
        const ext = path.extname(inputPath);
        const rule = this.rules.get(ext);
        if (!rule) throw new Error(`No cooker for ${ext}`);
        if (!this.needsUpdate(inputPath, outputPath)) return;
        await rule(inputPath, outputPath);
    }
    needsUpdate(src, dst) {
        try {
            return fs.statSync(src).mtime > fs.statSync(dst).mtime;
        } catch { return true; }
    }
}

