class PatchSystem {
    constructor() {
        this.installedVersion = null;
        this.baseUrl = 'https://cdn.game.com/patches/';
    }
    async checkForUpdates() {
        const manifest = await fetch(`${this.baseUrl}manifest.json`).then(r => r.json());
        if (manifest.version > this.installedVersion) {
            await this.downloadPatch(manifest);
        }
    }
    async downloadPatch(manifest) {
        const neededChunks = manifest.chunks.filter(c => !this.hasChunk(c.hash));
        for (const chunk of neededChunks) {
            const data = await fetch(`${this.baseUrl}${chunk.hash}`).then(r => r.arrayBuffer());
            await this.applyChunk(chunk, data);
            // Report progress
            this.onProgress?.(neededChunks.indexOf(chunk) / neededChunks.length);
        }
        this.installedVersion = manifest.version;
    }
}

