Subtitle Systems:
class SubtitleSystem {
    constructor() {
        this.queue = [];
        this.current = null;
        this.subtitlesEnabled = true;
        this.fontSize = 24;
    }
    play(text, duration, speaker = null) {
        this.queue.push({ text, duration, speaker, startTime: Date.now() });
    }
    update() {
        if (!this.subtitlesEnabled) return;
        const now = Date.now();
        if (this.current && now - this.current.startTime > this.current.duration * 1000) {
            this.current = null;
        }
        if (!this.current && this.queue.length > 0) {
            this.current = this.queue.shift();
            this.current.startTime = now;
        }
        if (this.current) {
            const elapsed = (now - this.current.startTime) / 1000;
            const progress = Math.min(1, elapsed / this.current.duration);
            const chars = Math.floor(progress * this.current.text.length);
            renderSubtitle(this.current.text.slice(0, chars), this.current.speaker);
        }
    }
}

