// SDF font rendering shader
#version 330 core
uniform sampler2D sdfTexture;
in vec2 uv;
out vec4 color;
uniform vec4 textColor;
uniform float smoothing; // 0.25 for crisp, 0.5 for soft

void main() {
    float distance = texture(sdfTexture, uv).r;
    float alpha = smoothstep(0.5 - smoothing, 0.5 + smoothing, distance);
    // Glow effect
    float glow = smoothstep(0.3, 0.5, distance) * 0.3;
    color = vec4(textColor.rgb, textColor.a * (alpha + glow));

    if (color.a < 0.01) discard;
}

