            'custom': null
        };
        this.custom = {};
        this.current = 'normal';
    }
    applyTo(enemy) {
        const d = this.presets[this.current];
        if (!d) return;
        enemy.damage *= d.enemyDamage;
        enemy.health *= d.enemyHealth;
        enemy.speed *= d.enemySpeed;
        enemy.aiReactionDelay = d.aiDelay;
    }
}

